import{z as s,x as A,o as r,c as p,q as o,j as i,D as e,d as t,s as C,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"LRC / ORC","description":"","frontmatter":{"title":"LRC / ORC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lrc-orc.md","filePath":"litho/lrc-orc.md","lastUpdated":1791063341000}'),d={name:"litho/lrc-orc.md"};function R(h,a,c,B,P,D){const E=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="lrc-orc" tabindex="-1">LRC / ORC <a class="header-anchor" href="#lrc-orc" aria-label="Permalink to &quot;LRC / ORC&quot;">​</a></h1><div class="epigraph"><p>OPC 负责把边推进目标；LRC 负责在交货前用同一套核再问一遍：过程角上还有没有桥、断、覆盖和 MRC 违约。</p><footer>—— 对照 lithography rule check / optical rule check 在计算光刻签核链中的公开定位</footer></div><p><a href="/litho/pwq">上一课</a>用硅上矩阵锚定缺陷窗。缺口是全芯片：不能对每块磁带都做 PWQ 矩阵。本课钉 LRC / ORC（lithography / optical rule check）——模型驱动的全场或准全场检查。哪些越界可以靠学习模型先排序，留给<a href="/litho/ml-hotspot-prediction">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OPC 收敛不等于可印：名义点贴目标时，PV-band 仍可能桥连、via 覆盖见光、SRAF 违 MRC、颜色分解后间距不够。LRC 在 OPC 之后、掩模书写之前，用签核模型扫轮廓与规则，输出热点表。ORC 是同一家族的光学侧称呼；有的流程把 MRC、着色、覆盖分项并进同一检查甲板。</p><p>缺口是<strong>签核门</strong>，不是再跑一次 OPC 迭代。LRC 失败应挡磁带，而不是开一张「已知问题」的无限豁免。与 <a href="/litho/mask-rule-check">MRC</a> 分工：MRC 问掩模厂能否写；LRC 问晶圆上过程角能否活。</p><h3 id="检查点不是优化点" tabindex="-1">检查点不是优化点 <a class="header-anchor" href="#检查点不是优化点" aria-label="Permalink to &quot;检查点不是优化点&quot;">​</a></h3><p>把 LRC 判据直接当 OPC 成本，循环会在规则与 EPE 之间振荡。实务是 OPC 用平滑目标，LRC 用硬阈值加人工/自动修复。PW-OPC 已经把窗带进优化；LRC 仍要独立跑，因为修复、fracture、MPC 之后几何会再变。</p><p><span class="marginnote">直觉类比：OPC 像教练把动作练到标准，LRC 像考前模拟卷——用同一套标准再考一遍，不合格就挡在考场外。若教练拿模拟卷评分当训练目标，动作会为应试而畸形；所以 LRC 判据不能直接当 OPC 的优化成本。</span></p><p><span class="marginnote">LRC 必须声明轮廓：ADI 还是 AEI、含不含套刻偏移、含不含随机判据。只报名义 CD 的 LRC 是空门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：OPC 后多边形、同一版本紧凑核、过程角集合（剂量、焦点、掩模偏置，有时套刻）。动作：仿真轮廓 → 量桥/断间距、CD、覆盖、PV-band 厚 → 对照规格。输出：按层、按单元、按密度分区的热点。与算力课衔接：过程角集合是账单旋钮；角太少，签核假绿。修复：局部重 OPC、改设计、或升格严格仿真确认误报。</p><p><span class="marginnote">术语翻译：PV-band（工艺变化带）是把剂量、焦点在规格范围内扫一遍后，同一图形轮廓铺开成的「可能地带」。LRC 的很多判据问的就是：这条带的边缘有没有压到桥连、断线或覆盖出界的线。</span></p><p>与 PWQ 对照：LRC 是模型代理，PWQ 抽检代理是否撒谎。两者热点应可互译。</p><p>检查甲板按层定制谓词：孔层重打开与覆盖，金属层重桥/断与 tip，切线层重套刻角。全球一套「最小间距」会漏掉层的主失效。Mentor / Synopsys 公开检查流把光学、MRC、着色分模块，签核仍要一张总门。</p>',15)),(r(),i(n,null,{default:e(()=>[C(E,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20DECK%5B%22%E6%A3%80%E6%9F%A5%E7%94%B2%E6%9D%BF%22%5D%20--%3E%20VIA%5B%22%E5%AD%94%E5%B1%82%3A%20%E6%89%93%E5%BC%80%20%2F%20via%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20DECK%20--%3E%20MET%5B%22%E9%87%91%E5%B1%9E%E5%B1%82%3A%20%E6%A1%A5%20%2F%20%E6%96%AD%20%2F%20tip-to-tip%22%5D%0A%20%20DECK%20--%3E%20CUT%5B%22%E5%88%87%E7%BA%BF%E5%B1%82%3A%20%E5%A5%97%E5%88%BB%E8%A7%92%22%5D%0A%20%20VIA%20--%3E%20WORST%5B%22%E5%90%84%E8%B0%93%E8%AF%8D%E5%9C%A8%E8%BF%87%E7%A8%8B%E8%A7%92%E4%B8%8A%E5%8F%96%E6%9C%80%E5%9D%8F%22%5D%0A%20%20MET%20--%3E%20WORST%0A%20%20CUT%20--%3E%20WORST%0A%20%20WORST%20--%3E%20HS%5B%22%E5%88%86%E5%8C%BA%E7%83%AD%E7%82%B9%E8%A1%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"轮廓由卷积核产生，检查是几何谓词（最小间距、包围、面积）。谓词在过程角上取最坏情况，等价于对 PV-band 做布尔。着色冲突、SRAF 放置失败会在更早的分解/OPC 步出现，但 LRC 是最后一次全场几何+光学联合。漏检的主因是模型残差，不是检查器「不够严」——残差课已经要求看空间相关；本课只要求 LRC 规格与残差图一起读。",-1)),(r(),i(n,null,{default:e(()=>[C(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPC%5B%22OPC%20%E5%90%8E%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%20--%3E%20LRC%5B%22%E8%BF%87%E7%A8%8B%E8%A7%92%E5%89%8D%E5%90%91%22%5D%0A%20%20LRC%20--%3E%20PRED%5B%22%E6%A1%A5%E6%96%AD%20%2F%20%E8%A6%86%E7%9B%96%20%2F%20MRC%22%5D%0A%20%20PRED%20--%3E%20GATE%5B%22%E6%8C%A1%E7%A3%81%E5%B8%A6%E6%88%96%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20PWQ%5B%22PWQ%20%E9%94%9A%22%5D%20--%3E%20CAL%5B%22%E6%A8%A1%E5%9E%8B%E4%BF%A1%E4%BB%BB%22%5D%0A%20%20CAL%20--%3E%20LRC%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>LRC 绿灯的含义是：在声明的过程角和核版本下，谓词未触发。换胶或换刻蚀核而不重跑，绿灯作废。这与模型残差课的「版本合同」是同一句话，写在磁带门上。</p><p><span class="marginnote">常见误区：把「LRC 绿灯」读成「绝对不出缺陷」。绿灯只保证在声明的过程角与模型版本下几何谓词没触发；模型残差、随机光子与颗粒缺陷都不归它管。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>LRC 不替代等离子体腔体签核，也不覆盖颗粒与随机光子。不把某 EDA 模块的「零热点」宣传当物理。曲线掩模的 LRC 谓词与曼哈顿不同，规格要重写。</p><p>后课默认：磁带前有模型全场门；下一课用学习模型给热点排序，不取代这扇门。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LRC/ORC 是 OPC 之后的过程角全场检查，挡的是磁带而不是再优化一圈。</li><li>轮廓定义（ADI/AEI、套刻、随机）必须写进门。</li><li>与 PWQ 互译；残差大则门不可信。</li><li>出处：计算光刻 LRC/ORC 签核通称；Mentor / Synopsys 公开检查流。</li></ul>',7))])}const u=s(d,[["render",R]]);export{L as __pageData,u as default};
